{
  "findings": [
    {
      "check_id": "CKV_AZURE_115",
      "title": "Function App should use Managed Identity instead of storage account access key",
      "resource": "azurerm_function_app.changeme_simple_function_app",
      "severity": "HIGH",
      "explanation": "Using storage account access keys directly in the Function App is a security risk as it exposes sensitive credentials. Managed Identity should be used to securely access the storage account."
    }
  ],
  "patched_code": "resource "azurerm_function_app" "changeme_simple_function_app" {
  name                       = "changeme-simple-function-app-name"
  location                   = azurerm_resource_group.changeme_simple_function_app_resource_group.location
  resource_group_name        = azurerm_resource_group.changeme_simple_function_app_resource_group.name
  app_service_plan_id        = azurerm_app_service_plan.changeme_simple_function_app_app_service_plan.id

  identity {
    type = "SystemAssigned"
  }

  storage_account_name = azurerm_storage_account.changeme_simple_function_app_storage_account.name
}

resource "azurerm_role_assignment" "changeme_function_app_storage_access" {
  scope                = azurerm_storage_account.changeme_simple_function_app_storage_account.id
  role_definition_name = "Storage Blob Data Contributor"
  principal_id         = azurerm_function_app.changeme_simple_function_app.identity[0].principal_id
}",
  "fix_summary": "Replaced the use of the storage account access key with a SystemAssigned Managed Identity for the Function App and added a role assignment to grant the Function App access to the storage account."
}
